import init, * as core from './wasm/pkg/musette_wasm';

let ready: Promise<typeof core> | undefined;

/** Load the Rust core once and return its exports. */
export function loadCore(): Promise<typeof core> {
  ready ??= init().then(() => core);
  return ready;
}

